import React from "react";

const Answer = ({
  question,
  options,
  selectedAnswer,
  correctAnswer,
  hint,
  explanation,
  difficulty,
  subject,
  topic,
}) => {
  return (
    <div className="bg-white rounded-lg p-6 mb-8 shadow-md border max-w-2xl mx-auto space-y-6">
      {/* Question */}
      <div className="space-y-2">
        <h3 className="text-lg font-medium text-gray-800">Question</h3>
        <p className="text-gray-700">{question}</p>
      </div>

      {/* Options */}
      <div className="space-y-2">
        <h4 className="text-lg font-medium text-gray-800">Options</h4>
        <ul className="space-y-3">
          {options?.map((option, index) => (
            <li
              key={index}
              className={`p-3 rounded-lg transition-all duration-150 text-gray-700 border ${
                option === options[selectedAnswer]
                  ? option === correctAnswer
                    ? "bg-green-100 border-green-300"
                    : "bg-red-100 border-red-300"
                  : option === correctAnswer
                  ? "bg-gray-50 border-gray-300"
                  : "border-transparent"
              }`}
            >
              {option}
            </li>
          ))}
        </ul>
      </div>

      {/* Feedback */}
      {selectedAnswer !== undefined && (
        <div
          className={`text-base font-medium text-center py-2 ${
            options[selectedAnswer] === correctAnswer
              ? "text-green-500"
              : "text-red-500"
          }`}
        >
          {options[selectedAnswer] === correctAnswer ? "Correct!" : "Incorrect"}
        </div>
      )}

      {/* Hint Section */}
      {hint && (
        <div className="bg-gray-50 p-3 rounded-lg border">
          <h4 className="font-medium text-gray-800">Hint</h4>
          <p className="text-gray-600 mt-1">{hint}</p>
        </div>
      )}

      {/* Explanation Section */}
      {explanation && (
        <div className="bg-gray-50 p-3 rounded-lg border">
          <h4 className="font-medium text-gray-800">Explanation</h4>
          <p className="text-gray-600 mt-1">{explanation}</p>
        </div>
      )}

      {/* Additional Info */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 text-sm text-gray-600">
        <div>
          <span className="font-medium text-gray-800">Difficulty:</span>{" "}
          <span className="capitalize">{difficulty || "N/A"}</span>
        </div>
        <div>
          <span className="font-medium text-gray-800">Subject:</span>{" "}
          <span>{subject || "N/A"}</span>
        </div>
        <div>
          <span className="font-medium text-gray-800">Topic:</span>{" "}
          <span>{topic || "N/A"}</span>
        </div>
      </div>
    </div>
  );
};

export default Answer;
